def createMaxNumber(nums1, nums2, k):
    def best_of(nums, t):
        drop = len(nums) - t
        stack = []
        for d in nums:
            while drop and stack and stack[-1] < d:
                stack.pop()
                drop -= 1
            stack.append(d)
        return stack[:t]

    def merge(a, b):
        res = []
        i = j = 0
        while i < len(a) or j < len(b):
            if a[i:] >= b[j:]:
                res.append(a[i])
                i += 1
            else:
                res.append(b[j])
                j += 1
        return res

    best = []
    for i in range(max(0, k - len(nums2)), min(k, len(nums1)) + 1):
        cand = merge(best_of(nums1, i), best_of(nums2, k - i))
        if cand > best:
            best = cand
    return best
